CREATE VIEW [dbo].[TMmanagerFuntion_View]
AS
SELECT          dbo.TMmanagerFunction.FunctionID, dbo.TMmanagerFunction.FunctionName, dbo.TMmanagerRole.RoleID, 
                            dbo.TMmanagerRole.RoleName
FROM              dbo.TMmanagerFunction LEFT OUTER JOIN
                            dbo.TMmanagerRoleFunctions ON 
                            dbo.TMmanagerFunction.FunctionID = dbo.TMmanagerRoleFunctions.FunctionID LEFT OUTER JOIN
                            dbo.TMmanagerRole ON dbo.TMmanagerRoleFunctions.RoleID = dbo.TMmanagerRole.RoleID
