CREATE VIEW [dbo].[TMmanagerAccount_View]
AS
SELECT          dbo.TMmanagerAccount.AccountID, dbo.TMmanagerAccount.UserName, dbo.TMmanagerAccount.PassWord, 
                            dbo.TMmanagerAccount.EmailAddress, dbo.TMmanagerAccount.PhoneNumber, dbo.TMmanagerAccount.LineID, 
                            dbo.TMmanagerAccount.WechatID, dbo.TMmanagerFunction.FunctionID, dbo.TMmanagerFunction.FunctionName, 
                            dbo.TMmanagerRole.RoleID, dbo.TMmanagerRole.RoleName, 
                            dbo.TMmanagerAccount.UpdateBy AS TMmanagerAccountUpdateBy, 
                            dbo.TMmanagerAccount.UpdateTime AS TMmanagerAccountUpdateTime, 
                            dbo.TMmanagerRole.UpdateBy AS TMmanagerRoleUpdateBy, 
                            dbo.TMmanagerRole.UpdateTime AS TMmanagerRoleUpdateTime, dbo.TMmanagerAccount.LastLogin
FROM              dbo.TMmanagerAccount LEFT OUTER JOIN
                            dbo.TMmanagerRoleAccounts ON 
                            dbo.TMmanagerAccount.AccountID = dbo.TMmanagerRoleAccounts.AccountID LEFT OUTER JOIN
                            dbo.TMmanagerRole ON dbo.TMmanagerRoleAccounts.RoleID = dbo.TMmanagerRole.RoleID LEFT OUTER JOIN
                            dbo.TMmanagerRoleFunctions ON 
                            dbo.TMmanagerRole.RoleID = dbo.TMmanagerRoleFunctions.RoleID LEFT OUTER JOIN
                            dbo.TMmanagerFunction ON dbo.TMmanagerRoleFunctions.FunctionID = dbo.TMmanagerFunction.FunctionID
