CREATE PROCEDURE [dbo].[GroupActionsRecursive]
	-- Add the parameters for the stored procedure here
	@ActionGroupName nvarchar(50), 
	@RMSName nvarchar(50),
	@ActionGroupNameParent nvarchar(50)
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
	WITH [GroupActions] AS (
	SELECT *
	FROM [SoftNetSYSDB].[dbo].[Actions]
	WHERE (ActionGroupName like '%' + @ActionGroupName + '%' or ActionParentGroupName like '%' + @ActionGroupName + '%') and RMSName = @RMSName
	and ActionGroupName like '%' + @ActionGroupNameParent + '%'
	UNION ALL
	--上面查出的結果 為依據遞迴查詢
	SELECT a.* 
	FROM [SoftNetSYSDB].[dbo].[Actions] a
	INNER JOIN [GroupActions] ga ON ga.ActionGroupName like a.ActionParentGroupName
	)
	SELECT distinct [ActionName],[RMSName],[ActionType],
	Cast(SetText as nvarchar(Max)) as SetText,
	case when (ActionType = '4' and Cast(SetValue as nvarchar(Max)) = 'true') then 'Start'
		 when (ActionType = '4' and Cast(SetValue as nvarchar(Max)) = 'false') then 'Stop' 
		 when (ActionType = '12' and Cast(SetValue as nvarchar(Max)) = 'true') then 'Start'
		 when (ActionType = '12' and Cast(SetValue as nvarchar(Max)) = 'false') then 'Stop'
	else Cast(SetValue as nvarchar(Max)) end as SetValue,
	[DeviceName],
	case when (ActionType = '3' and FCode = '5') then 'WriteSingleCoil(0x05)'
		 when (ActionType = '3' and FCode = '6') then 'WriteSingleRegister(0x06)'
		 when (ActionType = '3' and FCode = '15') then 'WriteMultipleCoils(0x15)'
	     when (ActionType = '3' and FCode = '16') then 'WriteMultipleRegisters(0x16)'
		 when (ActionType = '9' and FCode = '1') then 'Add'
	     when (ActionType = '9' and FCode = '2') then 'Remove'
		 when (ActionType = '9' and FCode = '3') then 'Add All'
		 when (ActionType = '9' and FCode = '4') then 'Remove All'
		 when (ActionType = '10' and FCode = '0') then ' '
		 when (ActionType = '10' and FCode = '1') then 'Cycle Time'
		 when (ActionType = '10' and FCode = '2') then 'Pass Times'
		 when (ActionType = '10' and FCode = '3') then 'Fail Times'
		 when (ActionType = '10' and FCode = '4') then 'Start Time'
		 when (ActionType = '10' and FCode = '5') then 'End Time'
	else FCode end as FCode, 
	Cast(MailTO as nvarchar(Max)) as MailTO,
	case when (ConvertValue = '0') then ' '
	when (ActionType = '3' and ConvertValue = '1') then 'Binary Convert to byte[]'
	when (ActionType = '3' and ConvertValue = '2') then 'ushort Convert to byte[]'
	when (ActionType = '3' and ConvertValue = '3') then 'int32 Convert to byte[]'
	when (ActionType = '3' and ConvertValue = '4') then 'float Convert to byte[]'
	when (ActionType = '3' and ConvertValue = '5') then 'string Convert to byte[]'
	when (ActionType = '14' and ConvertValue = '1') then 'Download'
	when (ActionType = '14' and ConvertValue = '2') then 'Upload'
	when (ActionType = '15' and ConvertValue = '1') then 'Download'
	when (ActionType = '15' and ConvertValue = '2') then 'Upload'
	else ConvertValue end as ConvertValue,[Remark],[UpdateUser],[UpdateTime]
	FROM [GroupActions]
END
		
GO
