CREATE PROCEDURE [dbo].[GroupThingsRecursive]
	-- Add the parameters for the stored procedure here
	@ThingGroupName nvarchar(50), 
	@RMSName nvarchar(50),
	@ThingGroupNameParent nvarchar(50)
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
	WITH [GroupThings] AS (
	SELECT *
	FROM [SoftNetSYSDB].[dbo].[Things]
	WHERE (ThingGroupName like '%' + @ThingGroupName + '%' or ThingParentGroupName like '%' + @ThingGroupName + '%') and RMSName = @RMSName
	and ThingGroupName like '%' + @ThingGroupNameParent + '%'
	UNION ALL
	--上面查出的結果 為依據遞迴查詢
	SELECT t.* 
	FROM [SoftNetSYSDB].[dbo].[Things] t
	INNER JOIN [GroupThings] gt ON gt.ThingGroupName like t.ThingParentGroupName
	)
	SELECT distinct ThingName,RMSName,ThingType,ValueType,Is_HistoryData,CaptureType,DeviceName,
	Modbus_FunCode, Modbus_StartAddr,Modbus_Len,Modbus_ConvertType,RMS_CaptureType,SQL_ConnectString,Cast(SQL_Language as nvarchar(Max)) as SQL_Language,
	Cast(SourceDefine as nvarchar(Max)) as SourceDefine,Flow_VariableName,File_PathName,Group_Name,Group_Attribute,Group_Status,Remark,Device_StatusFlag,HistoryDataByOne,
	Filter_Condition,Filter_Match,Filter_Value,ConvertValue,FilterMonitorName,UpdateUser,UpdateTime,SocketHeader,SocketTail,FlowProjectName,ThingGroupName,ThingParentGroupName
	FROM [GroupThings]
END
		
GO
