CREATE PROCEDURE [dbo].[WorkOrderProductionUpdate]
	@orderNo nvarchar(50),
	@serverId nvarchar(50)
AS
BEGIN
	-- Local Variables
	DECLARE @stationNo nvarchar(50)
	DECLARE @quantity int
	DECLARE @planUPH float
	DECLARE @tmpStationFPY float
	DECLARE @maxAvrageCycleTime float
	DECLARE @maxTotalOutput int
	DECLARE @lastStationOutput int
	DECLARE @maxCumlativeTime int
	DECLARE @isFinish int;

	--Result Variables for PP_WorkOrder
	DECLARE @fpy_o float
	DECLARE @yieldRate_o float
	DECLARE @planHours float
	DECLARE @remainingHours float
	DECLARE @actualUPH float
	DECLARE @achievingRateUPH float
	DECLARE @updateTime datetime

	-- Initial Variables
	SET @fpy_o = 1
	
	SELECT @isFinish = IIF(EndTime IS NOT NULL, 0, 1) FROM PP_WorkOrder WHERE ServerId = @serverId AND OrderNO = @orderNo

	-- UPDATE PP_WorkOrder.FPY
	IF @isFinish > 0
	BEGIN
		DECLARE table_cursor2 CURSOR FOR SELECT FPY FROM PP_WorkOrder_Settlement WHERE ServerId = @serverId AND OrderNO = @orderNo AND (TotalOutput>0 OR TotalFail>0)
		OPEN table_cursor2  
		FETCH NEXT FROM table_cursor2 INTO @tmpStationFPY
		WHILE @@FETCH_STATUS = 0  
		BEGIN		
			SET @fpy_o = @fpy_o * @tmpStationFPY
			FETCH NEXT FROM table_cursor2 INTO @tmpStationFPY 
		END
		CLOSE table_cursor2  
		DEALLOCATE table_cursor2 
	END	

	-- Get Order Information
	SELECT @quantity = Quantity,  @planUPH = PlanUPH FROM PP_WorkOrder WHERE ServerId = @serverId AND OrderNO = @orderNo

	-- Get @maxAvrageCycleTime, @maxTotalOutput, @maxCumlativeTime, 
	SELECT TOP 1 @maxAvrageCycleTime = AvarageCycleTime, @maxTotalOutput = TotalOutput, @maxCumlativeTime = CumulativeTime
	FROM PP_WorkOrder_Settlement
	WHERE ServerId = @serverId AND OrderNO = @orderNo ORDER BY AvarageCycleTime DESC

	--Last Station Output
	SELECT TOP 1 @lastStationOutput = TotalOutput
	FROM PP_WorkOrder_Settlement
	WHERE ServerId = @serverId AND OrderNO = @orderNo AND IsLastStation=1

	-- UPDATE PP_WorkOrder
	SET @planHours = IIF(@planUPH=0, 0, @quantity * 1.0 / @planUPH)
	SET @yieldRate_o = (SELECT AVG (TotalOutput * 1.0 / TotalInput) FROM PP_WorkOrder_Settlement WHERE ServerId = @serverId AND OrderNO = @orderNo AND TotalOutput > 0)
	SET @actualUPH = IIF(@maxCumlativeTime = 0  OR @maxCumlativeTime IS NULL OR @maxTotalOutput IS NULL, 0, (@maxTotalOutput*3600) / @maxCumlativeTime)
	SET @remainingHours = IIF(@maxAvrageCycleTime=0 OR @maxAvrageCycleTime IS NULL OR @lastStationOutput IS NULL OR @quantity - @lastStationOutput<0, 0,(@quantity - @lastStationOutput) * @maxAvrageCycleTime / 3600)
	SET @achievingRateUPH = IIF(@planUPH=0 OR @actualUPH IS NULL OR @planUPH IS NULL, 0, @actualUPH / @planUPH) 
	SET @updateTime = GETDATE();

	IF @yieldRate_o IS NULL
	BEGIN
		SET @yieldRate_o = 0
	END

	UPDATE PP_WorkOrder SET
		PlanHours = @planHours,
		FPY = @fpy_o,
		YieldRate = @yieldRate_o,
		RemainingHours = @remainingHours,
		ActualUPH = @actualUPH,
		AchievingRateUPH = @achievingRateUPH,
		UpdateTime = @updateTime
	WHERE ServerId = @serverId AND OrderNO = @orderNo
END
GO
